    22|// Prevent native splash from auto-hiding.
    23|SplashScreen.preventAutoHideAsync().catch(() => {});
    24|
    25|// Hard deadline: force-hide splash even if React never mounts useEffect.
    26|let splashFallbackTimer: ReturnType<typeof setTimeout> | null = setTimeout(() => {
    27|  splashFallbackTimer = null;
    28|  console.warn('[IVX] Splash hard deadline reached — forcing hide');
