    38|function VisibleLoadingScreen({ elapsedMs }: { elapsedMs: number }) {
    39|  useEffect(() => {
    40|    // Hide splash as soon as this visible loading screen paints.
    41|    requestAnimationFrame(() => {
    42|      logHideSplash();
    43|    });
