    87|const PROVIDER_LOAD_TIMEOUT_MS = 15000;
    88|
    89|export default function RootLayout() {
    90|  const [providersModule, setProvidersModule] = useState<{ AppProviders: React.ComponentType } | null>(null);
    91|  const [importError, setImportError] = useState<Error | null>(null);
    92|  const [startTime] = useState(() => Date.now());
    93|  const [elapsedMs, setElapsedMs] = useState(0);
    94|  const [attempt, setAttempt] = useState(0);
    95|
    96|  useEffect(() => {
    97|    const elapsedTimer = setInterval(() => {
    98|      setElapsedMs(Date.now() - startTime);
    99|    }, 200);
   100|    return () => clearInterval(elapsedTimer);
   101|  }, [startTime]);
   102|
   103|  useEffect(() => {
   104|    let cancelled = false;
   105|
   106|    const loadProviders = async () => {
   107|      if (!cancelled) {
   108|        setProvidersModule(null);
   109|        setImportError(null);
   110|      }
   111|      try {
   112|        const mod = await Promise.race([
   113|          import('./_providers'),
   114|          new Promise<never>((_, reject) =>
   115|            setTimeout(
   116|              () => reject(new Error(`Provider bundle load timed out after ${PROVIDER_LOAD_TIMEOUT_MS}ms`)),
   117|              PROVIDER_LOAD_TIMEOUT_MS,
   118|            ),
