   122|          setProvidersModule({ AppProviders: mod.AppProviders });
   123|        }
   124|      } catch (err) {
   125|        if (!cancelled) {
   126|          const error = err instanceof Error ? err : new Error(String(err));
   127|          console.error('[IVX] Provider import crashed:', error.message, error.stack);
   128|          setImportError(error);
   129|          logHideSplash();
   130|        }
   131|      }
   132|    };
   133|
   134|    // Defer provider loading to the next frame so the loading screen paints first.
   135|    const timer = setTimeout(() => {
   136|      void loadProviders();
   137|    }, 50);
   138|
   139|    return () => {
   140|      cancelled = true;
   141|      clearTimeout(timer);
   142|    };
   143|  }, [attempt]);
