   153|      <ImportCrashScreen
   154|        error={importError}
   155|        onRetry={() => setAttempt((a) => a + 1)}
   156|      />
   157|    );
   158|  }
   159|
   160|  // Phase 3: providers loaded successfully — render the full app.
   161|  const { AppProviders } = providersModule!;
   162|  return <AppProviders />;
