    64|class ProviderBoundary extends Component<ProviderBoundaryProps, ProviderBoundaryState> {
    65|  state: ProviderBoundaryState = { hasError: false, error: null, traceId: null };
    66|  static getDerivedStateFromError(error: Error): Partial<ProviderBoundaryState> {
