     1|/**
     2| * useRealtimeChannel — Canonical Supabase realtime hook with auto-reconnect.
     3| *
     4| * Features:
     5| * - Automatic reconnection with exponential backoff
     6| * - AppState-aware (subscribes on foreground, unsubscribes on background)
     7| * - Throttled query cache invalidation (no refetch storms)
     8| * - Delta cache updates (apply INSERT/UPDATE/DELETE directly to cache)
     9| * - Status surface for debugging
    10| * - Duplicate channel prevention
    11| * - Proper cleanup on unmount
    12| *
    13| * Usage:
    14| * ```tsx
    15| * useRealtimeChannel({
    16| *   channelName: 'projects-feed',
    17| *   table: 'properties',
    18| *   event: '*',
    19| *   filter: 'status=eq.active',
    20| *   queryKeys: [['projects']],
    21| *   onPayload: (payload) => console.log('Realtime event:', payload),
    22| * });
    23| * ```
    24| */
    25|import { useEffect, useRef, useState, useMemo, useCallback } from 'react';
    26|import { AppState, type AppStateStatus } from 'react-native';
    27|import { useQueryClient, type QueryClient } from '@tanstack/react-query';
    28|import { supabase, isSupabaseConfigured } from '@/lib/supabase';
    29|import type {
    30|  RealtimeChannel,
    31|  RealtimePostgresChangesPayload,
    32|} from '@supabase/supabase-js';
    33|
    34|// ─── Types ───────────────────────────────────────────────────────────
    35|
    36|export type RealtimeEvent = 'INSERT' | 'UPDATE' | 'DELETE' | '*';
    37|
    38|export interface RealtimeChannelConfig {
    39|  /** Unique channel name (prevents duplicates). */
    40|  channelName: string;
    41|  /** Supabase table to watch. */
    42|  table: string;
    43|  /** Database schema (default: 'public'). */
    44|  schema?: string;
    45|  /** Event type (default: '*'). */
    46|  event?: RealtimeEvent;
    47|  /** Optional filter (e.g. 'user_id=eq.123'). */
    48|  filter?: string;
    49|  /** React Query keys to invalidate on changes. */
    50|  queryKeys?: string[][];
    51|  /** Optional delta callback — apply changes directly to cache. */
    52|  onDelta?: (
    53|    queryClient: QueryClient,
    54|    event: RealtimeEvent,
    55|    record: Record<string, unknown>,
    56|  ) => void;
    57|  /** Optional raw payload callback. */
    58|  onPayload?: (
    59|    payload: RealtimePostgresChangesPayload<Record<string, unknown>>,
    60|  ) => void;
    61|}
    62|
    63|export type RealtimeStatus =
    64|  | 'idle'
    65|  | 'connecting'
    66|  | 'connected'
    67|  | 'disconnected'
    68|  | 'reconnecting'
    69|  | 'error'
    70|  | 'not_configured';
    71|
    72|export interface RealtimeChannelState {
    73|  status: RealtimeStatus;
    74|  reconnectAttempt: number;
    75|  lastEventAt: number | null;
    76|  lastError: string | null;
    77|}
    78|
    79|// ─── Constants ───────────────────────────────────────────────────────
    80|
    81|const INVALIDATION_THROTTLE_MS = 2_000;
    82|const MAX_RECONNECT_ATTEMPTS = 10;
    83|const BASE_BACKOFF_MS = 1_000;
    84|const MAX_BACKOFF_MS = 30_000;
    85|
    86|// ─── Throttled invalidation ──────────────────────────────────────────
    87|
    88|const _lastInvalidation = new Map<string, number>();
    89|
    90|function throttledInvalidate(
    91|  queryClient: QueryClient,
    92|  keys: string[][],
    93|  throttleMs: number = INVALIDATION_THROTTLE_MS,
    94|): void {
    95|  const now = Date.now();
    96|  for (const key of keys) {
    97|    const keyStr = JSON.stringify(key);
    98|    const last = _lastInvalidation.get(keyStr) ?? 0;
    99|    if (now - last < throttleMs) continue;
   100|    _lastInvalidation.set(keyStr, now);
   101|    void queryClient.invalidateQueries({ queryKey: key });
   102|  }
   103|}
   104|
   105|// ─── Default delta applier ───────────────────────────────────────────
   106|
   107|function defaultDeltaApplier(
   108|  queryClient: QueryClient,
   109|  queryKeyPrefix: string[],
   110|  event: RealtimeEvent,
   111|  record: Record<string, unknown>,
   112|): void {
   113|  const recordId = String(record.id ?? '');
   114|  if (!recordId) return;
   115|
   116|  queryClient.setQueriesData<{ items: unknown[]; hasMore: boolean }>(
   117|    { queryKey: queryKeyPrefix },
   118|    (cached) => {
   119|      if (!cached || !Array.isArray(cached.items)) return cached;
   120|      const items = cached.items as Array<Record<string, unknown> & { id?: string }>;
   121|      const existingIndex = items.findIndex((item) => String(item?.id) === recordId);
   122|
   123|      switch (event) {
   124|        case 'INSERT': {
   125|          if (existingIndex >= 0) {
   126|            const updated = [...items];
   127|            updated[existingIndex] = record as any;
   128|            return { ...cached, items: updated };
   129|          }
   130|          return { ...cached, items: [record as any, ...items] };
   131|        }
   132|        case 'UPDATE': {
   133|          if (existingIndex >= 0) {
   134|            const updated = [...items];
   135|            updated[existingIndex] = record as any;
   136|            return { ...cached, items: updated };
   137|          }
   138|          return cached;
   139|        }
   140|        case 'DELETE': {
   141|          if (existingIndex >= 0) {
   142|            return { ...cached, items: items.filter((_, i) => i !== existingIndex) };
   143|          }
   144|          return cached;
   145|        }
   146|        default:
   147|          return cached;
   148|      }
   149|    },
   150|  );
   151|}
   152|
   153|// ─── Hook ────────────────────────────────────────────────────────────
   154|
   155|export function useRealtimeChannel(
   156|  configs: RealtimeChannelConfig[],
